/**
 * ATLAS DOMAIN SPECIFICATION CONTRACT V1
 * 
 * Formal declarative specification schema generated by Atlas Search Factory.
 * Completely eliminates manual TypeScript codegen for vertical search engines.
 * 
 * Invariants:
 * - Specification is self-contained, serializable to JSON, and fully versioned.
 * - Categorizes fields: CORE_IDENTITY, SEARCHABLE, FACET, DISPLAY, RELATION, TEMPORAL, EVIDENCE_ONLY, RESTRICTED.
 * - Enforces zero name-only merges and strong identity anchors.
 * - Accompanied by governance gates and discovery plan.
 */

import type { DomainUIConfig } from '../../fabric/contracts/AtlasDomainPack';

export type FieldClassification = 
  | 'CORE_IDENTITY'
  | 'SEARCHABLE'
  | 'FACET'
  | 'DISPLAY'
  | 'RELATION'
  | 'TEMPORAL'
  | 'EVIDENCE_ONLY'
  | 'RESTRICTED';

export interface FieldSpecification {
  name: string;
  type: 'string' | 'number' | 'boolean' | 'array' | 'date' | 'object';
  classification: FieldClassification;
  required: boolean;
  nullable: boolean;
  searchable: boolean;
  facetable: boolean;
  sensitivity: 'PUBLIC' | 'COMMERCIAL_PUBLIC' | 'RESTRICTED_CONTACT' | 'CONFIDENTIAL';
  evidence_required: boolean;
  description: string;
}

export interface GovernancePolicySpec {
  access_gate: { required: boolean; allowed_schemes: string[] };
  license_gate: { required: boolean; commercial_reuse_mandated: boolean; public_domain_acceptable: boolean };
  privacy_gate: { required: boolean; allow_private_individuals: false; allow_residential_addresses: false };
  purpose_gate: { required: boolean; allowed_purposes: string[] };
  commercial_reuse_gate: { required: boolean; require_explicit_commercial_authorization: boolean };
}

export interface SourceCandidateSpec {
  source_id: string;
  source_name: string;
  source_url: string;
  source_family: string;
  openness_tier: 'OPEN_API' | 'BULK_DATASET' | 'TABLE_SCRAPE' | 'RESTRICTED';
  initial_status: 'SOURCE_CANDIDATE';
  scale_estimate: number;
  depth_estimate: number;
  governance_checks: {
    access_passed?: boolean;
    license_passed?: boolean;
    privacy_passed?: boolean;
    purpose_passed?: boolean;
    commercial_reuse_passed?: boolean;
    failure_reason?: string;
  };
}

export interface DiscoveryPlanSpec {
  explorer_targets: string[];
  deep_miner_targets: string[];
  protocol_hunter_endpoints: string[];
  replicator_dimensions: string[];
  unlocker_strategies: string[];
}

export interface AtlasDomainSpecification {
  domain_id: string;
  spec_version: string; // e.g. "1.0.0"
  generator_version: string; // e.g. "SEARCH_FACTORY_V1"
  natural_language_goal: string;
  created_at: string;
  updated_at: string;

  // Domain Metadata
  entity_type: string; // e.g. "COMPANY", "SUPPLIER"
  display_name: string;
  sector_scope: string;
  geographic_scope: string;
  target_audience: string;

  // Schema & Fields
  fields: FieldSpecification[];

  // Identity & Deduplication Policy
  identity_policy: {
    primary_id_field: string;
    strong_identifier_fields: string[];
    secondary_identifier_fields: string[];
    weak_signal_fields: string[];
    allow_soft_canonical_merge: false; // STRICTLY FALSE across all domains
    allow_name_only_merge: false;       // STRICTLY FALSE
    collision_action: 'REJECT' | 'PROBABLE_SAME_ENTITY';
    dedup_strategy: 'STRONG_HASH_MATCH' | 'REGISTRY_ID_MATCH' | 'DOMAIN_SPECIFIC';
  };

  // Evidence & Provenance
  evidence_policy: {
    require_source_url: boolean;
    require_confidence: boolean;
    min_confidence_to_persist: number;
    require_observed_at: boolean;
  };

  // Source Governance & Strategy
  governance_policy: GovernancePolicySpec;
  source_candidates: SourceCandidateSpec[];

  // Discovery Strategy for Penta-Radar
  discovery_plan: DiscoveryPlanSpec;

  // Search, Facets & Ranking
  searchable_fields: string[];
  facets: string[];
  ranking_factors: {
    field: string;
    weight: number;
    match_type: 'exact' | 'fuzzy' | 'recency' | 'numeric_range';
  }[];
  default_sort: { field: string; direction: 'asc' | 'desc' };

  // Coverage Dimensions (for Gap Engine & Completeness)
  coverage_dimensions: string[];

  // Freshness & Decay
  freshness_policy: {
    stale_threshold_days: number;
    auto_refresh_queue_priority: number;
  };

  // UI Configuration for Search App Shell
  ui_config: DomainUIConfig;
}

export const ATLAS_DOMAIN_SPECIFICATION_VERSION = '1.0.0';
